/// <reference types="vite/client" />

/**
 * Vite environment variable type declarations.
 *
 * WHAT:
 *   This file tells TypeScript about the shape of import.meta.env.
 *   The `/// <reference types="vite/client" />` directive imports Vite's
 *   built-in type definitions, which include:
 *     - import.meta.env.VITE_*  (string | undefined for custom vars)
 *     - import.meta.env.MODE    (string)
 *     - import.meta.env.DEV     (boolean)
 *     - import.meta.env.PROD    (boolean)
 *
 * WHY:
 *   Without this file, TypeScript does not know what import.meta.env contains
 *   and reports errors like "Property 'env' does not exist on type 'ImportMeta'".
 *   This is the standard Vite solution — generated by `npm create vite`.
 *
 * CUSTOM ENV VARS:
 *   The ImportMetaEnv interface below extends Vite's defaults with our
 *   VITE_-prefixed variables. This gives TypeScript-checked access to
 *   import.meta.env.VITE_API_URL etc.
 */

interface ImportMetaEnv {
  readonly VITE_API_URL: string;
  readonly VITE_COGNITO_USER_POOL_ID: string;
  readonly VITE_COGNITO_APP_CLIENT_ID: string;
  readonly VITE_AWS_REGION: string;
}

interface ImportMeta {
  readonly env: ImportMetaEnv;
}
